// Сетка средней температуры суши и океана; источник и нормы описаны рядом.
import { gunzipSync } from 'fflate';
import { MAP_PIXELS } from '../config';

const TEMPERATURE_GRID_GZIP =
  '' +
  '' +
  '' +
  '' +
  '' +
  '' +
  '' +
  '' +
  '';
const BASE64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
let decoded: Int16Array | null = null;

function decodeBase64(text: string): Uint8Array {
  const lookup = new Int16Array(128).fill(-1);
  for (let index = 0; index < BASE64.length; index += 1) lookup[BASE64.charCodeAt(index)] = index;
  const output = new Uint8Array(Math.floor((text.length * 3) / 4));
  let bits = 0, count = 0, position = 0;
  for (let index = 0; index < text.length; index += 1) {
    const value = lookup[text.charCodeAt(index)];
    if (value < 0) continue;
    bits = (bits << 6) | value; count += 6;
    if (count >= 8) { count -= 8; output[position++] = (bits >> count) & 255; }
  }
  return output.subarray(0, position);
}

export function earthMeanTemperatureDeciC(): Int16Array {
  if (decoded) return decoded;
  const bytes = gunzipSync(decodeBase64(TEMPERATURE_GRID_GZIP));
  if (bytes.byteLength !== MAP_PIXELS * 2) throw new Error('Сетка температуры имеет неверный размер.');
  const values = new Int16Array(MAP_PIXELS);
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  for (let pixel = 0; pixel < MAP_PIXELS; pixel += 1) values[pixel] = view.getInt16(pixel * 2, true);
  decoded = values;
  return values;
}

export function fillEarthMeanTemperature(target: Float32Array): void {
  if (target.length !== MAP_PIXELS) throw new RangeError('Размер растра температуры не совпадает с картой.');
  const values = earthMeanTemperatureDeciC();
  for (let pixel = 0; pixel < MAP_PIXELS; pixel += 1) target[pixel] = values[pixel] / 10;
}
